"""Label Champion Memory — per-label similarity champion with fill.

Combines the coverage guarantee of label-balanced selection with the
relevance focus of similarity retrieval:

1. Champion pass: for each seen label, pick the single stored example
   whose raw_question is most Jaccard-similar to the current query.
   Champions are then ranked by their similarity scores.

2. Fill pass: after one champion per label, add remaining examples in
   similarity-score order until the context budget is exhausted.

This ensures every seen label appears at least once while still
prioritising the most topically relevant example for each label.
Similarity is measured on raw_question only (not the full input) to
avoid score dilution from shared instruction boilerplate.
"""

import collections
import hashlib
import json
import re
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem below based on the examples provided.

{examples_section}

**Problem:**
{input}

**Instructions:**
- Follow the patterns shown in the examples above
- Respond in JSON format

{{"reasoning": "[your reasoning]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000


def _tokenize(text: str) -> frozenset[str]:
    return frozenset(re.findall(r"[A-Za-z0-9]+", text.lower()))


def _jaccard(a: frozenset[str], b: frozenset[str]) -> float:
    if not a and not b:
        return 0.0
    return len(a & b) / len(a | b)


class LabelChampionMemory(MemorySystem):
    """Per-label champion retrieval: best match per label, then fill by score."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, Any]] = []

    def _select(self, query: str) -> list[str]:
        if not self.examples:
            return []

        q_tok = _tokenize(query)

        # Group by label; compute similarity for each example
        by_label: dict[str, list[tuple[float, int, dict]]] = collections.defaultdict(list)
        for idx, ex in enumerate(self.examples):
            score = _jaccard(q_tok, ex["tokens"])
            by_label[ex["target"]].append((score, idx, ex))

        # Champion pass: pick best-scoring (most recent on ties) example per label
        champion_indices: set[int] = set()
        champions: list[tuple[float, int, dict]] = []
        for label, scored_exs in by_label.items():
            best = max(scored_exs, key=lambda x: (x[0], x[1]))
            champions.append(best)
            champion_indices.add(best[1])

        champions.sort(key=lambda x: (x[0], x[1]), reverse=True)

        parts: list[str] = []
        total_chars = 0

        for _score, _idx, ex in champions:
            q = ex.get("raw_question", ex["input"])
            part = f"Q: {q}\nA: {ex['target']}"
            if total_chars + len(part) + 2 > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2

        # Fill pass: remaining non-champion examples ranked by similarity
        remaining: list[tuple[float, int, dict]] = []
        for idx, ex in enumerate(self.examples):
            if idx in champion_indices:
                continue
            score = _jaccard(q_tok, ex["tokens"])
            remaining.append((score, idx, ex))
        remaining.sort(key=lambda x: (x[0], x[1]), reverse=True)

        for _score, _idx, ex in remaining:
            q = ex.get("raw_question", ex["input"])
            part = f"Q: {q}\nA: {ex['target']}"
            if total_chars + len(part) + 2 > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2

        return parts

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        parts = self._select(input)
        examples_section = "\n\n".join(parts)
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
            "num_selected": len(parts),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for r in batch_results:
            raw_q = r.get("raw_question", r["input"])
            ex: dict[str, Any] = {
                "input": r["input"],
                "target": r["ground_truth"],
                "tokens": _tokenize(raw_q),
            }
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        return sum(len(p) + 2 for p in self._select(""))

    def get_state(self) -> str:
        serialisable = [
            {k: (sorted(v) if isinstance(v, frozenset) else v) for k, v in ex.items()}
            for ex in self.examples
        ]
        return json.dumps({"examples": serialisable}, indent=2)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = []
        for ex in data.get("examples", []):
            restored = dict(ex)
            if "tokens" in restored and isinstance(restored["tokens"], list):
                restored["tokens"] = frozenset(restored["tokens"])
            else:
                raw_q = restored.get("raw_question", restored.get("input", ""))
                restored["tokens"] = _tokenize(raw_q)
            self.examples.append(restored)

"""Similarity Retrieval Memory - retrieve examples most similar to the current query.

At predict time, ranks all stored examples by token-level Jaccard similarity
to the current query, then fills the context budget with the highest-scoring
examples. This targets tasks with structured inputs (e.g. domain-specific
syntax or vocabulary) where the most similar training examples are more
informative than the most recent ones.

Selection algorithm:
  - Tokenise query and every stored example's raw_question by alphanumeric
    sequences (case-folded).
  - Score each example by Jaccard(query_tokens, example_tokens).
  - Sort descending by score (break ties by recency).
  - Fill context greedily until char budget is exhausted.

This is a fundamentally different retrieval mechanism from fewshot_all (recency),
contrastive_error_memory (recency + error priority), and reflexion_memory (LLM
synthesis). No LLM is called in learn_from_batch, keeping learning cost zero.
"""

import hashlib
import json
import re
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem below based on the examples provided.

{examples_section}

**Problem:**
{input}

**Instructions:**
- Follow the patterns shown in the examples above
- Respond in JSON format

{{"reasoning": "[your reasoning]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000


def _tokenize(text: str) -> frozenset[str]:
    """Return lowercase alphanumeric tokens from text."""
    return frozenset(re.findall(r"[A-Za-z0-9]+", text.lower()))


def _jaccard(a: frozenset[str], b: frozenset[str]) -> float:
    if not a and not b:
        return 0.0
    return len(a & b) / len(a | b)


def _stable_hash(text: str) -> int:
    return int.from_bytes(hashlib.sha256(text.encode()).digest()[:8], "big")


class SimilarityRetrievalMemory(MemorySystem):
    """Retrieve examples by Jaccard token similarity to the current query."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        # Each entry: {"input": ..., "target": ..., "raw_question": ..., "tokens": frozenset}
        self.examples: list[dict[str, Any]] = []

    def _select_by_similarity(self, query: str) -> list[str]:
        """Rank examples by similarity to query, fill context budget greedily."""
        if not self.examples:
            return []

        q_tokens = _tokenize(query)

        # Score and rank: (score, arrival_index, example)
        # Use arrival_index as secondary sort key so ties go to most recent
        scored = [
            (_jaccard(q_tokens, ex["tokens"]), idx, ex)
            for idx, ex in enumerate(self.examples)
        ]
        scored.sort(key=lambda x: (x[0], x[1]), reverse=True)

        parts: list[str] = []
        total_chars = 0
        for _score, _idx, ex in scored:
            question = ex.get("raw_question", ex["input"])
            part = f"Q: {question}\nA: {ex['target']}"
            if total_chars + len(part) + 2 > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2

        return parts

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        parts = self._select_by_similarity(input)
        examples_section = "\n\n".join(parts)
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
            "num_selected": len(parts),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for r in batch_results:
            raw_q = r.get("raw_question", r["input"])
            ex: dict[str, Any] = {
                "input": r["input"],
                "target": r["ground_truth"],
                "tokens": _tokenize(raw_q),
            }
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        # Use a short generic query for the length estimate
        return sum(len(p) + 2 for p in self._select_by_similarity(""))

    def get_state(self) -> str:
        # frozenset is not JSON-serialisable — convert to sorted list for storage
        serialisable = [
            {k: (sorted(v) if isinstance(v, frozenset) else v) for k, v in ex.items()}
            for ex in self.examples
        ]
        return json.dumps({"examples": serialisable}, indent=2)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = []
        for ex in data.get("examples", []):
            restored = dict(ex)
            # Restore tokens as frozenset from stored list
            if "tokens" in restored and isinstance(restored["tokens"], list):
                restored["tokens"] = frozenset(restored["tokens"])
            else:
                raw_q = restored.get("raw_question", restored.get("input", ""))
                restored["tokens"] = _tokenize(raw_q)
            self.examples.append(restored)

"""MMR Memory — Maximum Marginal Relevance retrieval.

At each greedy step, selects the stored example that maximises:

    score(e) = λ * sim(e, query) − (1−λ) * max_{s ∈ selected} sim(e, s)

This balances relevance to the current query against redundancy with
already-chosen examples, so the context window receives a diverse,
topically-relevant set without requiring explicit label bookkeeping.

Unlike pure similarity ranking (which clusters on the most frequent
topic) or round-robin (which treats every label as equally useful),
MMR adapts the diversity penalty to the actual redundancy observed in
the retrieved set.

Similarity is measured on raw_question only to avoid dilution from
shared instruction boilerplate. λ=0.6 weights relevance slightly
over diversity, preserving topical focus while penalising near-duplicate
examples.

Reference: Carbonell & Goldstein, SIGIR 1998.
"""

import json
import re
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem below based on the examples provided.

{examples_section}

**Problem:**
{input}

**Instructions:**
- Follow the patterns shown in the examples above
- Respond in JSON format

{{"reasoning": "[your reasoning]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000
LAMBDA = 0.6  # relevance weight; 1-LAMBDA is diversity weight


def _tokenize(text: str) -> frozenset[str]:
    return frozenset(re.findall(r"[A-Za-z0-9]+", text.lower()))


def _jaccard(a: frozenset[str], b: frozenset[str]) -> float:
    if not a and not b:
        return 0.0
    return len(a & b) / len(a | b)


class MmrMemory(MemorySystem):
    """Greedy MMR selection: relevant to query, diverse from already-chosen examples."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, Any]] = []

    def _select_mmr(self, query: str) -> list[str]:
        if not self.examples:
            return []

        q_tok = _tokenize(query)

        # Pre-compute relevance and token sets for all stored examples
        pool = [
            {
                "ex": ex,
                "tok": ex["tokens"],
                "rel": _jaccard(q_tok, ex["tokens"]),
                "idx": i,
            }
            for i, ex in enumerate(self.examples)
        ]

        selected_parts: list[str] = []
        selected_toks: list[frozenset[str]] = []
        total_chars = 0
        remaining = list(range(len(pool)))

        while remaining:
            best_score: float | None = None
            best_ri: int | None = None

            for ri in remaining:
                item = pool[ri]
                rel = item["rel"]
                if selected_toks:
                    redundancy = max(_jaccard(item["tok"], st) for st in selected_toks)
                else:
                    redundancy = 0.0
                mmr = LAMBDA * rel - (1 - LAMBDA) * redundancy

                if best_score is None or mmr > best_score:
                    best_score = mmr
                    best_ri = ri

            item = pool[best_ri]
            ex = item["ex"]
            q = ex.get("raw_question", ex["input"])
            part = f"Q: {q}\nA: {ex['target']}"

            if total_chars + len(part) + 2 > MAX_CHARS:
                break

            selected_parts.append(part)
            selected_toks.append(item["tok"])
            total_chars += len(part) + 2
            remaining.remove(best_ri)

        return selected_parts

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        parts = self._select_mmr(input)
        examples_section = "\n\n".join(parts)
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )
        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
            "num_selected": len(parts),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for r in batch_results:
            raw_q = r.get("raw_question", r["input"])
            ex: dict[str, Any] = {
                "input": r["input"],
                "target": r["ground_truth"],
                "tokens": _tokenize(raw_q),
            }
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        return sum(len(p) + 2 for p in self._select_mmr(""))

    def get_state(self) -> str:
        serialisable = [
            {k: (sorted(v) if isinstance(v, frozenset) else v) for k, v in ex.items()}
            for ex in self.examples
        ]
        return json.dumps({"examples": serialisable}, indent=2)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = []
        for ex in data.get("examples", []):
            restored = dict(ex)
            if "tokens" in restored and isinstance(restored["tokens"], list):
                restored["tokens"] = frozenset(restored["tokens"])
            else:
                raw_q = restored.get("raw_question", restored.get("input", ""))
                restored["tokens"] = _tokenize(raw_q)
            self.examples.append(restored)

